import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadLalitadityaData(){const t=readFileSync(resolve(__dirname,"../../lalitaditya-muktapida-explorer/lalitaditya-data.js"),"utf-8");return new Function(t+"\nreturn { LALITADITYA_INFO, MARTAND_SUN_TEMPLE, CAMPAIGNS_AND_HISTORIOGRAPHY, TIMELINE_EVENTS, REFERENCES };")()}describe("Lalitaditya Muktapida Explorer — Data Tests",()=>{let t;beforeAll(()=>{t=loadLalitadityaData()}),describe("LALITADITYA_INFO metadata",()=>{it("contains correct Lalitaditya metadata and Karkota dynasty",()=>{expect(t.LALITADITYA_INFO.id).toBe("lalitaditya-muktapida"),expect(t.LALITADITYA_INFO.title).toContain("Lalitaditya"),expect(t.LALITADITYA_INFO.dynasty).toContain("Karkota"),expect(t.LALITADITYA_INFO.monumentalLegacy).toContain("Martand Sun Temple")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(t.LALITADITYA_INFO.quickStats)).toBe(!0),expect(t.LALITADITYA_INFO.quickStats.length).toBe(6)})}),describe("MARTAND_SUN_TEMPLE & CAMPAIGNS",()=>{it("contains Martand temple details and campaign historiography",()=>{expect(t.MARTAND_SUN_TEMPLE.title).toContain("Martand"),expect(Array.isArray(t.MARTAND_SUN_TEMPLE.highlights)).toBe(!0),expect(t.MARTAND_SUN_TEMPLE.highlights.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(t.CAMPAIGNS_AND_HISTORIOGRAPHY)).toBe(!0),expect(t.CAMPAIGNS_AND_HISTORIOGRAPHY.length).toBeGreaterThanOrEqual(4)})}),describe("TIMELINE_EVENTS & REFERENCES",()=>{it("contains reign timeline and reference sources",()=>{expect(Array.isArray(t.TIMELINE_EVENTS)).toBe(!0),expect(t.TIMELINE_EVENTS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(t.REFERENCES)).toBe(!0),expect(t.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});